{
  "prompt": {
    "examples": [
      "Front-facing 'invisible' action-cam on a skydiver in freefall above bright clouds; camera locked on his face. He speaks over the wind with clear lipsync: 'This is insanely fun! You've got to try it—book a tandem and go!' Natural wind roar, voice close-mic'd and slightly compressed so it's intelligible. Midday sun, goggles and jumpsuit flutter, altimeter visible, parachute rig on shoulders. Energetic but stable framing with subtle shake; brief horizon roll. End on first tug of canopy and wind noise dropping."
    ],
    "minLength": 1,
    "type": "string",
    "title": "Prompt",
    "description": "The text prompt describing the video you want to generate",
    "maxLength": 5000
  },
  "detect_and_block_ip": {
    "type": "boolean",
    "title": "Detect And Block Ip",
    "description": "If enabled, the prompt (and image for image-to-video) will be checked for known intellectual property references and the request will be blocked if any are detected.",
    "default": false
  },
  "aspect_ratio": {
    "default": "auto",
    "enum": [
      "auto",
      "9:16",
      "16:9"
    ],
    "type": "string",
    "title": "Aspect Ratio",
    "description": "The aspect ratio of the generated video"
  },
  "duration": {
    "default": 4,
    "enum": [
      4,
      8,
      12,
      16,
      20
    ],
    "type": "integer",
    "title": "Duration",
    "description": "Duration of the generated video in seconds"
  },
  "character_ids": {
    "anyOf": [
      {
        "maxItems": 2,
        "type": "array",
        "items": {
          "type": "string"
        }
      },
      {
        "type": "null"
      }
    ],
    "description": "Up to two character IDs (from create-character) to use in the video. Refer to characters by name in the prompt. When set, only the OpenAI provider is used.",
    "title": "Character IDs"
  },
  "model": {
    "default": "sora-2",
    "enum": [
      "sora-2",
      "sora-2-2025-12-08",
      "sora-2-2025-10-06"
    ],
    "type": "string",
    "title": "Model",
    "description": "The model to use for the generation. When the default model is selected, the latest snapshot of the model will be used - otherwise, select a specific snapshot of the model."
  },
  "image_url": {
    "examples": [
      "https://storage.googleapis.com/falserverless/example_inputs/sora-2-i2v-input.png"
    ],
    "type": "string",
    "title": "Image URL",
    "description": "The URL of the image to use as the first frame"
  },
  "resolution": {
    "default": "auto",
    "enum": [
      "auto",
      "720p"
    ],
    "type": "string",
    "title": "Resolution",
    "description": "The resolution of the generated video"
  },
  "delete_video": {
    "default": true,
    "type": "boolean",
    "title": "Delete Video",
    "description": "Whether to delete the video after generation for privacy reasons. If True, the video cannot be used for remixing and will be permanently deleted."
  }
}

